from produire import produire,paras,steps,table
from medicaments import carbomere
parts=[
('La {sécheresse oculaire} est une altération de l’équilibre du film lacrymal et de la surface de l’œil. Elle peut résulter d’un manque de larmes ou d’une évaporation excessive. Elle ne se réduit pas à une simple sensation de sable.',paras('Quantité et qualité des larmes interviennent ensemble. Une dysfonction des glandes de Meibomius, une inflammation et une altération du clignement peuvent participer au tableau.', 'La sécheresse peut être isolée ou associée à une maladie générale, un médicament ou une anomalie palpébrale. Le diagnostic doit expliquer les symptômes sans masquer une autre cause de rougeur.')),
('Le {contexte est souvent multifactoriel}. Âge, environnement sec, travail visuel prolongé et médicaments peuvent contribuer. Des maladies inflammatoires ou une mauvaise fermeture palpébrale doivent être recherchées.',paras('La fréquence augmente avec l’âge ; elle est notamment élevée après la ménopause. Ces tendances ne fournissent pas un taux suisse individuel.', 'Rechercher syndrome de Sjögren, polyarthrite, chirurgie oculaire, lentilles et maladies des paupières selon l’histoire. Un facteur environnemental plausible ne dispense pas de l’examen de la cornée.')),
('Le {mécanisme entretient instabilité et inflammation}. Un film lacrymal instable peut devenir trop concentré en sels. La surface s’irrite et perd une part de sa protection.',paras('Une production aqueuse réduite et une évaporation accrue peuvent coexister. Les sécrétions des glandes de Meibomius contribuent à limiter l’évaporation.', 'Le clignement répartit les larmes ; une fermeture incomplète expose davantage la cornée. Une atteinte épithéliale peut donner douleur, gêne et vision fluctuante, voire des complications dans les formes sévères.')),
('Le {tri recherche une atteinte cornéenne ou une autre urgence}. Douleur importante, photophobie, baisse visuelle persistante ou rougeur aiguë inhabituelle nécessite un avis rapide. Ne pas attribuer tout symptôme à une sécheresse déjà connue.',paras('Un porteur de lentilles avec œil rouge doit être évalué pour une kératite. Une infection, une uvéite ou une complication après chirurgie peut coexister avec une sécheresse.', 'Une cornée opaque, un point blanc ou une impossibilité de fermer correctement l’œil demande une évaluation adaptée. Le soulagement transitoire sous larmes artificielles n’exclut pas une maladie grave.')),
('L’{anamnèse précise gêne et facteurs aggravants}. Rechercher brûlure, sable, fluctuations visuelles et retentissement quotidien. Demander exposition au vent, fumée, climatisation et écrans.',paras('Noter rythme des symptômes, clignement, lentilles et chirurgie antérieure. Une vision fluctuante peut accompagner une surface instable ; une baisse persistante ne doit pas être banalisée.', 'Revoir médicaments et produits oculaires, notamment fréquence et conservateurs. Demander sécheresse buccale, douleurs articulaires et autres signes systémiques pour orienter un bilan ciblé, sans le rendre automatique.')),
('L’{examen étudie surface et paupières}. Mesurer la vision et observer clignement, fermeture et bords palpébraux. La lampe à fente et des colorants peuvent préciser l’atteinte.',paras('L’ophtalmologue évalue production, stabilité du film et signes de souffrance de la surface. Les tests sont interprétés ensemble avec les symptômes et le contexte.', 'Rechercher anomalies des glandes de Meibomius, blépharite, malposition palpébrale ou exposition cornéenne. Une plainte importante avec peu de signes exige une réévaluation plutôt qu’une négation de la gêne.')),
('L’{approche syndromique recherche le mécanisme dominant}. Insuffisance aqueuse et évaporation ne s’excluent pas. Une autre affection de surface peut coexister.',table(['Composante','Orientation'],[['Production lacrymale réduite.','Rechercher âge, médicaments ou contexte systémique selon l’histoire.'],['Évaporation excessive.','Examiner glandes palpébrales, clignement et environnement.'],['Exposition cornéenne.','Vérifier fermeture et position des paupières.'],['Prurit ou sécrétions.','Allergie, blépharite ou infection concurrente à discuter.'],['Douleur et baisse visuelle persistante.','Ne pas conclure à une sécheresse simple ; avis spécialisé.']])) ,
('Le {diagnostic associe symptômes et examen}. Aucun produit essayé ne constitue à lui seul un test de confirmation. Les examens spécialisés précisent le type et la sévérité.',paras('Les HUG décrivent une démarche fondée sur entretien, examen instrumental et colorants. Les résultats doivent être reliés au terrain et aux diagnostics concurrents.', 'La réponse à un lubrifiant peut aider à la prise en charge mais ne prouve pas que toute la gêne provient du film lacrymal. Une atteinte sévère requiert un suivi de la cornée.')),
('Les {examens complémentaires sont orientés}. Un bilan systémique n’est pas nécessaire pour chaque irritation. Il devient pertinent si les symptômes ou l’examen évoquent une maladie associée.',paras('Les HUG mentionnent, selon le syndrome suspecté, des analyses sanguines ou une exploration salivaire en collaboration avec le médecin traitant. L’objectif est d’identifier une cause précise, pas de prescrire un panel uniforme.', 'Les tests spécialisés de film lacrymal et les colorations dépendent du matériel et du protocole. Un résultat isolé ne suffit pas à expliquer tous les symptômes ; sa portée dépend de la méthode et de l’examen complet.')),
('L’{algorithme associe tri et traitement progressif}. La sécurité cornéenne est vérifiée avant une simple lubrification prolongée. Les facteurs causaux sont revus à chaque étape.',steps('Rechercher baisse visuelle, douleur importante, photophobie, lentilles et contexte opératoire.', 'Examiner vision, surface, paupières et fermeture ; orienter rapidement si alarme.', 'Identifier facteurs environnementaux, médicaments et éventuel contexte systémique.', 'Proposer mesures adaptées et lubrification dans l’indication de la spécialité.', 'Réévaluer efficacité, tolérance et besoin de traitement spécialisé.')),
('La {prise en charge suisse combine cause et symptômes}. Adapter environnement, pauses visuelles et soins des paupières selon le mécanisme. Une lubrification peut réduire l’inconfort.',paras('Les HUG privilégient les préparations sans conservateur lorsque cela est adapté, notamment si les instillations sont fréquentes. Un médicament suspect est revu avec son prescripteur ; ne pas l’arrêter seul.', '@@MEDICAMENTS@@', 'Une composante évaporative liée aux glandes palpébrales peut bénéficier de soins locaux adaptés. Les traitements anti-inflammatoires, la ciclosporine, le sérum autologue ou les dispositifs de conservation des larmes relèvent d’une indication spécialisée.', 'Les formes avec exposition ou lésion cornéenne peuvent nécessiter un geste spécifique. Aucun traitement ne garantit une guérison définitive de toutes les causes ; l’objectif est de contrôler symptômes, inflammation et risque de lésion.')),
('Le {suivi adapte le traitement à la réponse}. Vérifier observance, technique d’instillation et tolérance des conservateurs. Les changements de vision ou de douleur imposent une nouvelle évaluation.',paras('Réduire fumée, air sec et exposition directe aux flux d’air, et organiser des pauses lors du travail visuel prolongé. Adapter le port de lentilles avec le professionnel ; préférer les lunettes si le port entretient les symptômes.', 'Une aggravation ou une absence d’amélioration attendue doit faire revoir la cause. Une maladie générale ou une anomalie palpébrale ne se traite pas uniquement en augmentant le nombre de gouttes.')),
('Le {point clé} est de traiter un mécanisme identifié et de protéger la cornée. Les larmes artificielles soulagent sans résoudre toutes les causes. Une baisse visuelle persistante n’est pas une manifestation à banaliser.',paras('Quantité de larmes, évaporation, inflammation, clignement et terrain sont complémentaires. Le suivi garde ouvert le diagnostic si les symptômes ne correspondent plus à une forme simple.'))]
quiz=[('La sécheresse est-elle toujours un manque de quantité ?','Non, qualité et évaporation comptent aussi.'),('Les mécanismes peuvent-ils se combiner ?','Oui.'),('Quel rôle jouent les glandes de Meibomius ?','Leurs sécrétions contribuent à limiter l’évaporation.'),('Une sécheresse connue exclut-elle une kératite ?','Non.'),('Une baisse visuelle persistante peut-elle être banalisée ?','Non.'),('Quels éléments palpébraux examiner ?','Clignement, fermeture, position et bords des paupières.'),('Un lubrifiant qui soulage prouve-t-il seul le diagnostic ?','Non.'),('Le bilan sanguin est-il systématique ?','Non, il dépend de la suspicion clinique.'),('Pourquoi revoir les médicaments ?','Certains peuvent contribuer à la sécheresse.'),('Peut-on arrêter seul un traitement général suspect ?','Non, le revoir avec son prescripteur.'),('Pourquoi discuter les conservateurs ?','Ils peuvent irriter la surface, surtout lors d’utilisation fréquente.'),('La dose Viscotears adulte est-elle automatiquement pédiatrique ?','Non, sécurité et efficacité pédiatriques ne sont pas établies dans cette notice.'),('Les corticoïdes locaux sont-ils un traitement autonome de routine ?','Non, indication et suivi spécialisés.'),('Quel est l’objectif du suivi ?','Contrôler gêne et cause tout en protégeant la cornée.')]
produire(4,parts,quiz,(1,6,13,14,15),carbomere)
